//! Behaviour of the dist scan, the rendered table and the generator.

use std::fmt::Write;
use std::fs;
use std::path::Path;

use gang_embed::{Bundle, EmbedError, Entry, generate};
use sha2::{Digest, Sha256};

const HELLO_ETAG: &str = "\"2cf24dba5fb0a30e26e83b2ac5b9e29e1b161e5c1fa7425e73043362938b9824\"";
const EMPTY_TABLE: &str = concat!(
    "// Generated by gang-embed; do not edit.\n",
    "\n",
    "use crate::Asset;\n",
    "\n",
    "pub(crate) static ASSETS: &[Asset] = &[];\n"
);
const HTML_TYPE: &str = "text/html; charset=utf-8";
const JS_TYPE: &str = "text/javascript; charset=utf-8";
const CSS_TYPE: &str = "text/css; charset=utf-8";
const WOFF2_TYPE: &str = "font/woff2";

fn write(root: &Path, rel: &str, bytes: &[u8]) {
    let path = root.join(rel);
    if let Some(parent) = path.parent() {
        fs::create_dir_all(parent).expect("create fixture parent directory");
    }
    fs::write(&path, bytes).expect("write fixture file");
}

fn ok<T>(result: Result<T, EmbedError>, what: &str) -> T {
    match result {
        Ok(value) => value,
        Err(error) => panic!("{what} failed: {error}"),
    }
}

fn scan(root: &Path) -> Bundle {
    ok(Bundle::scan(root), "scan")
}

fn find<'a>(bundle: &'a Bundle, path: &str) -> &'a Entry {
    bundle
        .entries()
        .iter()
        .find(|entry| entry.path == path)
        .unwrap_or_else(|| panic!("no entry for {path}"))
}

fn paths(bundle: &Bundle) -> Vec<&str> {
    bundle
        .entries()
        .iter()
        .map(|entry| entry.path.as_str())
        .collect()
}

fn hex(bytes: &[u8]) -> String {
    bytes
        .iter()
        .fold(String::with_capacity(bytes.len() * 2), |mut s, b| {
            write!(s, "{b:02x}").unwrap();
            s
        })
}

fn etag_of(bytes: &[u8]) -> String {
    format!("\"{}\"", hex(&Sha256::digest(bytes)))
}

#[test]
fn scan_attaches_only_present_variants() {
    let dir = tempfile::tempdir().expect("tempdir");
    let root = dir.path();
    write(root, "index.html", b"<html></html>");
    write(root, "index.html.gz", b"gz-index");
    write(root, "index.html.br", b"br-index");
    write(root, "assets/app-1.js", b"console.log(1);");
    write(root, "assets/app-1.js.br", b"br-app");
    write(root, "assets/font-1.woff2", b"woff2-bytes");

    let bundle = scan(root);

    assert_eq!(
        paths(&bundle),
        vec!["assets/app-1.js", "assets/font-1.woff2", "index.html"],
        "entries must be sorted by path and exclude variant files"
    );

    let index = find(&bundle, "index.html");
    assert!(index.br, "index.html must have a br variant");
    assert!(index.gz, "index.html must have a gz variant");
    assert!(!index.immutable, "index.html must not be immutable");

    let app = find(&bundle, "assets/app-1.js");
    assert!(app.br, "assets/app-1.js must have a br variant");
    assert!(!app.gz, "assets/app-1.js must not have a gz variant");
    assert!(app.immutable, "assets/app-1.js must be immutable");

    let font = find(&bundle, "assets/font-1.woff2");
    assert!(!font.br, "font must not have a br variant");
    assert!(!font.gz, "font must not have a gz variant");
    assert!(font.immutable, "font under assets/ must be immutable");
}

#[test]
fn etag_is_quoted_sha256_of_identity_bytes() {
    let dir = tempfile::tempdir().expect("tempdir");
    write(dir.path(), "hello.txt", b"hello");

    let bundle = scan(dir.path());

    assert_eq!(
        find(&bundle, "hello.txt").etag,
        HELLO_ETAG,
        "etag must be the quoted lowercase hex SHA-256 of the identity bytes"
    );
}

#[test]
fn etag_changes_with_content() {
    let changed_a = tempfile::tempdir().expect("tempdir");
    write(changed_a.path(), "app.js", b"alpha");
    let changed_b = tempfile::tempdir().expect("tempdir");
    write(changed_b.path(), "app.js", b"alphb");

    let etag_a = find(&scan(changed_a.path()), "app.js").etag.clone();
    let etag_b = find(&scan(changed_b.path()), "app.js").etag.clone();
    assert_ne!(
        etag_a, etag_b,
        "one differing byte must produce a different etag"
    );

    let first = tempfile::tempdir().expect("tempdir");
    write(first.path(), "b.txt", b"two");
    write(first.path(), "a.txt", b"one");
    let second = tempfile::tempdir().expect("tempdir");
    write(second.path(), "a.txt", b"one");
    write(second.path(), "b.txt", b"two");

    let first_bundle = scan(first.path());
    let second_bundle = scan(second.path());
    assert_eq!(
        find(&first_bundle, "a.txt").etag,
        find(&second_bundle, "a.txt").etag,
        "identical trees must yield equal etags regardless of creation order"
    );
    assert_eq!(
        find(&first_bundle, "b.txt").etag,
        find(&second_bundle, "b.txt").etag,
        "identical trees must yield equal etags regardless of creation order"
    );
    assert_eq!(
        first_bundle.render("../dist"),
        second_bundle.render("../dist"),
        "identical trees must render identically regardless of creation order"
    );
}

#[test]
fn content_types_follow_extensions() {
    let dir = tempfile::tempdir().expect("tempdir");
    let root = dir.path();
    write(root, "index.html", b"<html></html>");
    write(root, "assets/app-1.js", b"console.log(1);");
    write(root, "assets/site-1.css", b"body {}");
    write(root, "assets/font-1.woff2", b"woff2-bytes");

    let bundle = scan(root);

    assert_eq!(find(&bundle, "index.html").content_type, HTML_TYPE);
    assert_eq!(find(&bundle, "assets/app-1.js").content_type, JS_TYPE);
    assert_eq!(find(&bundle, "assets/site-1.css").content_type, CSS_TYPE);
    assert_eq!(
        find(&bundle, "assets/font-1.woff2").content_type,
        WOFF2_TYPE
    );
}

#[test]
fn orphan_variant_is_an_error() {
    let dir = tempfile::tempdir().expect("tempdir");
    write(dir.path(), "assets/a.js.gz", b"orphan");

    match Bundle::scan(dir.path()) {
        Err(EmbedError::OrphanVariant { path }) => {
            assert_eq!(
                path, "assets/a.js.gz",
                "orphan variant path must be reported"
            );
        }
        Ok(_) => panic!("expected OrphanVariant error, scan succeeded"),
        Err(other) => panic!("expected OrphanVariant error, got: {other}"),
    }
}

#[test]
fn missing_dist_is_a_read_error() {
    let dir = tempfile::tempdir().expect("tempdir");
    let missing = dir.path().join("does-not-exist");

    match Bundle::scan(&missing) {
        Err(EmbedError::Read { .. }) => {}
        Ok(_) => panic!("expected Read error for missing dist, scan succeeded"),
        Err(other) => panic!("expected Read error for missing dist, got: {other}"),
    }
}

#[test]
fn empty_dist_renders_an_empty_table() {
    let dir = tempfile::tempdir().expect("tempdir");

    let bundle = scan(dir.path());

    assert!(
        bundle.entries().is_empty(),
        "empty dist must have no entries"
    );
    assert_eq!(
        bundle.render("../dist"),
        EMPTY_TABLE,
        "empty dist must render an empty table"
    );
}

#[test]
fn render_is_deterministic_and_sorted() {
    let dir = tempfile::tempdir().expect("tempdir");
    let root = dir.path();
    write(root, "index.html", b"<html></html>");
    write(root, "assets/app-1.js", b"console.log(1);");
    write(root, "assets/app-1.js.br", b"br-app");
    write(root, "assets/site-1.css", b"body {}");

    let rendered = scan(root).render("../dist");
    let rendered_again = scan(root).render("../dist");
    assert_eq!(rendered, rendered_again, "rendering must be deterministic");

    let path_lines: Vec<&str> = rendered
        .lines()
        .filter(|line| line.trim_start().starts_with("path: "))
        .collect();
    assert_eq!(path_lines.len(), 3, "one path line per entry");
    let mut sorted = path_lines.clone();
    sorted.sort_unstable();
    assert_eq!(path_lines, sorted, "path lines must be in sorted order");

    assert!(
        rendered.contains(r#"include_bytes!("../dist/assets/app-1.js.br")"#),
        "variant must be embedded via include_bytes! relative to the generated file:\n{rendered}"
    );
    assert!(
        rendered.contains("br: None,"),
        "absent variant must render as None:\n{rendered}"
    );

    let mut current: Option<&str> = None;
    for line in rendered.lines() {
        let trimmed = line.trim();
        if let Some(rest) = trimmed.strip_prefix("path: \"") {
            current = rest.strip_suffix("\",");
        } else if trimmed.starts_with("immutable: ") {
            let path = current.expect("immutable line must follow its path line");
            let expected = if path.starts_with("assets/") {
                "immutable: true,"
            } else {
                "immutable: false,"
            };
            assert_eq!(trimmed, expected, "immutable flag wrong for {path}");
        }
    }
}

#[test]
fn generate_writes_the_rendered_bundle() {
    let dir = tempfile::tempdir().expect("tempdir");
    let dist = dir.path().join("dist");
    write(&dist, "index.html", b"<html></html>");
    write(&dist, "index.html.gz", b"gz-index");
    let out_dir = dir.path().join("out");
    fs::create_dir_all(&out_dir).expect("create output directory");
    let out = out_dir.join("assets.rs");

    ok(generate(&dist, &out), "generate");

    let written = fs::read_to_string(&out).expect("read generated file");
    assert_eq!(
        written,
        scan(&dist).render("../dist"),
        "generated file must equal the rendered bundle"
    );

    let missing_parent = dir.path().join("missing").join("out.rs");
    match generate(&dist, &missing_parent) {
        Err(EmbedError::Write { .. }) => {}
        Ok(()) => panic!("expected Write error for missing parent directory"),
        Err(other) => panic!("expected Write error, got: {other}"),
    }
}

#[test]
fn generate_computes_the_root_from_the_output_directory() {
    let dir = tempfile::tempdir().expect("tempdir");

    let nested_dist = dir.path().join("a").join("dist");
    write(&nested_dist, "index.html", b"<html></html>");
    let nested_out_dir = dir.path().join("b").join("c");
    fs::create_dir_all(&nested_out_dir).expect("create output directory");
    let nested_out = nested_out_dir.join("assets.rs");
    ok(generate(&nested_dist, &nested_out), "generate");
    assert_includes_start_with(&nested_out, r#"include_bytes!("../../a/dist/"#);

    let sibling_dist = dir.path().join("dist");
    write(&sibling_dist, "index.html", b"<html></html>");
    let sibling_out = dir.path().join("assets.rs");
    ok(generate(&sibling_dist, &sibling_out), "generate");
    assert_includes_start_with(&sibling_out, r#"include_bytes!("dist/"#);
}

fn assert_includes_start_with(out: &Path, prefix: &str) {
    let written = fs::read_to_string(out).expect("read generated file");
    let includes: Vec<&str> = written
        .lines()
        .filter(|line| line.contains("include_bytes!("))
        .collect();
    assert!(
        !includes.is_empty(),
        "generated file must embed the dist assets"
    );
    for line in includes {
        assert!(
            line.contains(prefix),
            "include path must start with {prefix}: {line}"
        );
    }
}

#[cfg(unix)]
#[test]
fn symlinked_files_are_followed() {
    use std::os::unix::fs::symlink;

    let outside = tempfile::tempdir().expect("tempdir");
    let target = outside.path().join("target.js");
    fs::write(&target, b"linked bytes").expect("write symlink target");
    let real_dir = outside.path().join("theme-src");
    write(&real_dir, "inner.css", b"body{}");

    let dist = tempfile::tempdir().expect("tempdir");
    write(dist.path(), "index.html", b"<html></html>");
    symlink(&target, dist.path().join("linked.js")).expect("symlink file");
    symlink(&real_dir, dist.path().join("theme")).expect("symlink directory");

    let bundle = scan(dist.path());

    let linked = find(&bundle, "linked.js");
    assert_eq!(
        linked.etag,
        etag_of(b"linked bytes"),
        "symlinked file must hash the target's bytes"
    );
    assert_eq!(linked.content_type, JS_TYPE);

    let inner = find(&bundle, "theme/inner.css");
    assert_eq!(
        inner.etag,
        etag_of(b"body{}"),
        "file inside symlinked directory must be walked and hashed"
    );
}
